from pathlib import Path
import shutil


ROOT = Path.cwd()
TEST1 = ROOT / "tests" / "test_phase157_r20_repair37_short_exact_after_map_support.py"
TEST2 = ROOT / "tests" / "test_phase159_r1_7b_exact_sequence_display_order.py"
BACKUP_DIR = ROOT / "phase159_r1_7b_repair4_backup_before_apply"

TEST1_CONTENT = 'import re\n\nfrom toda_calculation_facade import (\n  build_standard_toda_report,\n)\nfrom toda_group_proof_narrative_renderer import (\n  render_toda_group_proof_narrative_markdown,\n)\nfrom toda_group_proof_presentation import (\n  build_toda_group_proof_presentation,\n)\nfrom toda_group_result_proof_replay import (\n  build_toda_group_result_proof_replay,\n)\n\n\ndef _body_pi6_3_repair37() -> str:\n  report = build_standard_toda_report(\n    n=3,\n    k=3,\n  )\n  group_result = (\n    report\n    .candidates[0]\n    .source_candidate.group_result\n  )\n  replay = build_toda_group_result_proof_replay(\n    group_result,\n    max_depth=2,\n  )\n  presentation = build_toda_group_proof_presentation(\n    replay\n  )\n  rendered = render_toda_group_proof_narrative_markdown(\n    presentation\n  )\n\n  return rendered.split(\n    "\\n## 証明\\n",\n    1,\n  )[1]\n\n\ndef _normalized_display_blocks(\n  markdown: str,\n) -> tuple[\n  str,\n  ...,\n]:\n  blocks = re.findall(\n    r"\\\\\\[\\s*(.*?)\\s*\\\\\\]",\n    markdown,\n    flags=re.DOTALL,\n  )\n\n  return tuple(\n    re.sub(\n      r"\\s+",\n      "",\n      block,\n    ).rstrip(\n      "."\n    )\n    for block in blocks\n  )\n\n\ndef test_phase157_r20_repair37_short_exact_follows_surjectivity():\n  body = _body_pi6_3_repair37()\n\n  surjectivity = (\n    r"$H: \\pi_{6}^{3} \\to \\pi_{6}^{5}$ "\n    "は全射."\n  )\n  reason = (\n    "この完全性と, 左の写像が単射, "\n    "右の写像が全射であることより, "\n    "次の短完全列を得る."\n  )\n  normalized_short_exact = re.sub(\n    r"\\s+",\n    "",\n    (\n      r"0\\longrightarrow \\pi_{5}^{2}"\n      r"\\xrightarrow{E} \\pi_{6}^{3}"\n      r"\\xrightarrow{H} \\pi_{6}^{5}"\n      r"\\longrightarrow 0"\n    ),\n  )\n\n  assert surjectivity in body\n  assert reason in body\n  assert normalized_short_exact in (\n    _normalized_display_blocks(\n      body\n    )\n  )\n\n  short_exact_start = body.index(\n    r"\\[",\n    body.index(\n      reason\n    ),\n  )\n\n  assert body.index(\n    surjectivity\n  ) < body.index(\n    reason\n  )\n  assert body.index(\n    reason\n  ) < short_exact_start\n\n\ndef test_phase157_r20_repair37_short_exact_follows_injectivity():\n  body = _body_pi6_3_repair37()\n\n  injectivity = (\n    r"$E: \\pi_{5}^{2} \\to \\pi_{6}^{3}$ "\n    "は単射."\n  )\n  normalized_short_exact = re.sub(\n    r"\\s+",\n    "",\n    (\n      r"0\\longrightarrow \\pi_{5}^{2}"\n      r"\\xrightarrow{E} \\pi_{6}^{3}"\n      r"\\xrightarrow{H} \\pi_{6}^{5}"\n      r"\\longrightarrow 0"\n    ),\n  )\n\n  assert injectivity in body\n  assert normalized_short_exact in (\n    _normalized_display_blocks(\n      body\n    )\n  )\n\n  short_exact_start = body.index(\n    r"\\[",\n    body.index(\n      injectivity\n    ),\n  )\n\n  assert body.index(\n    injectivity\n  ) < short_exact_start\n'
TEST2_CONTENT = 'import re\n\nfrom toda_calculation_facade import (\n  build_standard_toda_report,\n)\nfrom toda_group_proof_narrative_renderer import (\n  render_toda_group_proof_narrative_markdown,\n)\nfrom toda_group_proof_presentation import (\n  build_toda_group_proof_presentation,\n)\nfrom toda_group_result_proof_replay import (\n  build_toda_group_result_proof_replay,\n)\n\n\ndef _phase159_r1_7b_render(\n  n: int,\n  k: int,\n) -> str:\n  report = build_standard_toda_report(\n    n=n,\n    k=k,\n  )\n  group_result = (\n    report\n    .candidates[\n      0\n    ].source_candidate.group_result\n  )\n  replay = build_toda_group_result_proof_replay(\n    group_result,\n    max_depth=2,\n  )\n  presentation = build_toda_group_proof_presentation(\n    replay\n  )\n\n  return render_toda_group_proof_narrative_markdown(\n    presentation\n  )\n\n\ndef _normalized_display_blocks(\n  markdown: str,\n) -> tuple[\n  str,\n  ...,\n]:\n  blocks = re.findall(\n    r"\\\\\\[\\s*(.*?)\\s*\\\\\\]",\n    markdown,\n    flags=re.DOTALL,\n  )\n\n  return tuple(\n    re.sub(\n      r"\\s+",\n      "",\n      block,\n    ).rstrip(\n      "."\n    )\n    for block in blocks\n  )\n\n\ndef _normalized_latex(\n  latex: str,\n) -> str:\n  return re.sub(\n    r"\\s+",\n    "",\n    latex,\n  ).rstrip(\n    "."\n  )\n\n\ndef test_phase159_r1_7b_pi6_3_short_exact_sequence_is_display_math():\n  rendered = _phase159_r1_7b_render(\n    3,\n    3,\n  )\n  expected = _normalized_latex(\n    r"0\\longrightarrow \\pi_{5}^{2}"\n    r"\\xrightarrow{E} \\pi_{6}^{3}"\n    r"\\xrightarrow{H} \\pi_{6}^{5}"\n    r"\\longrightarrow 0"\n  )\n\n  assert expected in (\n    _normalized_display_blocks(\n      rendered\n    )\n  )\n  assert (\n    r"$0\\longrightarrow \\pi_{5}^{2}"\n    not in rendered\n  )\n\n\ndef test_phase159_r1_7b_pi11_4_delta_surjectivity_has_matching_exactness_before_it():\n  rendered = _phase159_r1_7b_render(\n    4,\n    7,\n  )\n  expected = _normalized_latex(\n    r"\\pi_{10}^{3} \\xrightarrow{H} \\pi_{10}^{5} "\n    r"\\xrightarrow{\\Delta} \\pi_{8}^{2}"\n  )\n  surjectivity = (\n    r"$\\Delta: \\pi_{10}^{5} \\to \\pi_{8}^{2}$"\n    " は全射."\n  )\n\n  assert expected in (\n    _normalized_display_blocks(\n      rendered\n    )\n  )\n  assert surjectivity in rendered\n\n  displays = list(\n    re.finditer(\n      r"\\\\\\[\\s*(.*?)\\s*\\\\\\]",\n      rendered,\n      flags=re.DOTALL,\n    )\n  )\n  matching = next(\n    match\n    for match in displays\n    if (\n      _normalized_latex(\n        match.group(\n          1\n        )\n      )\n      == expected\n    )\n  )\n  surjectivity_index = rendered.index(\n    surjectivity\n  )\n  reason_index = rendered.rfind(\n    "完全性より,",\n    matching.end(),\n    surjectivity_index,\n  )\n\n  assert matching.start() < reason_index\n  assert reason_index < surjectivity_index\n\n\ndef test_phase159_r1_7b_pi11_4_visible_exactness_windows_use_display_math():\n  rendered = _phase159_r1_7b_render(\n    4,\n    7,\n  )\n  expected = _normalized_latex(\n    r"\\pi_{9}^{2} \\xrightarrow{E} \\pi_{10}^{3} "\n    r"\\xrightarrow{H} \\pi_{10}^{5}"\n  )\n\n  assert expected in (\n    _normalized_display_blocks(\n      rendered\n    )\n  )\n  assert (\n    r"$\\pi_{9}^{2} \\xrightarrow{E} \\pi_{10}^{3}"\n    not in rendered\n  )\n'


def main() -> int:
  for path in (TEST1, TEST2):
    if not path.exists():
      raise RuntimeError(f"missing test file: {path}")

  BACKUP_DIR.mkdir(parents=True, exist_ok=True)
  shutil.copy2(TEST1, BACKUP_DIR / TEST1.name)
  shutil.copy2(TEST2, BACKUP_DIR / TEST2.name)

  TEST1.write_text(TEST1_CONTENT, encoding="utf-8")
  TEST2.write_text(TEST2_CONTENT, encoding="utf-8")

  print("Phase 159-R1-7b repair4 applied.")
  print("Production code changes: none")
  print("Updated stale/brittle focused tests only.")
  return 0


if __name__ == "__main__":
  raise SystemExit(main())
